        private void ConfigurarCampo(
            System.Windows.Forms.TextBox campo,
            string texto,
            int x,
            int y)
        {
            campo.Location = new System.Drawing.Point(x, y);
            campo.Name = texto.Replace(" ", "_");
            campo.Size = new System.Drawing.Size(215, 25);
            campo.Text = texto;
            campo.ForeColor = System.Drawing.Color.Gray;

            campo.Enter += (sender, e) =>
            {
                if (campo.ForeColor == System.Drawing.Color.Gray)
                {
                    campo.Text = "";
                    campo.ForeColor = System.Drawing.Color.Black;
                }
            };

            campo.Leave += (sender, e) =>
            {
                if (string.IsNullOrWhiteSpace(campo.Text))
                {
                    campo.Text = texto;
                    campo.ForeColor = System.Drawing.Color.Gray;
                }
            };
        }
